	"database/sql"
	"encoding/json"
	"net/http"
	"os"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec(`CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT, category TEXT, price REAL)`)
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Laptop', 'High performance laptop', 'Electronics', 999.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Desk Chair', 'Ergonomic office chair', 'Furniture', 299.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Coffee Maker', 'Automatic drip coffee maker', 'Appliances', 49.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Headphones', 'Wireless noise-cancelling', 'Electronics', 199.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Notebook', '200 page spiral notebook', 'Stationery', 4.99)")

