package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec(`CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT, category TEXT, price REAL)`)
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Laptop', 'High performance laptop', 'Electronics', 999.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Desk Chair', 'Ergonomic office chair', 'Furniture', 299.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Coffee Maker', 'Automatic drip coffee maker', 'Appliances', 49.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Headphones', 'Wireless noise-cancelling', 'Electronics', 199.99)")
	db.Exec("INSERT INTO products (name, description, category, price) VALUES ('Notebook', '200 page spiral notebook', 'Stationery', 4.99)")

	http.HandleFunc("/search", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		q := r.URL.Query().Get("q")
		category := r.URL.Query().Get("category")

		conditions := []string{}
		args := []interface{}{}
		if q != "" {
			conditions = append(conditions, "(name LIKE ? OR description LIKE ?)")
			p := "%" + q + "%"
			args = append(args, p, p)
		}
		if category != "" {
			conditions = append(conditions, "category = ?")
			args = append(args, category)
		}
		sql := "SELECT id, name, description, category, price FROM products"
		if len(conditions) > 0 {
			sql += " WHERE " + strings.Join(conditions, " AND ")
		}
		sql += " ORDER BY name"

		rows, _ := db.Query(sql, args...)
		var products []map[string]interface{}
		for rows.Next() {
			var id int
			var name, desc, cat string
			var price float64
			rows.Scan(&id, &name, &desc, &cat, &price)
			products = append(products, map[string]interface{}{"id": id, "name": name, "description": desc, "category": cat, "price": price})
		}
		json.NewEncoder(w).Encode(products)
		_ = fmt.Sprintf("%s", "")
	})

	http.ListenAndServe(":"+port, nil)
}
